// Consumes the /orders pagination API described in backend/contract.json:
//   request:  { page: integer starting at 1 }
//   response: { items: array of { id: string }, next_page: integer or null }
export async function fetchAll(fetchPage) {
  const items = [];
  let page = 1;
  do {
    const data = await fetchPage({ page });
    if (!Array.isArray(data.items)) {
      throw new Error(`/orders page ${page}: response is missing the "items" array (see backend/contract.json)`);
    }
    if (data.next_page !== null && !Number.isInteger(data.next_page)) {
      throw new Error(`/orders page ${page}: "next_page" must be an integer or null (see backend/contract.json)`);
    }
    items.push(...data.items);
    page = data.next_page;
  } while (page != null);
  return items;
}
